// ---- 00_util.js ----
// Worldbound Nakama server module. Generated into ../modules/index.js by
// tools/build_server_module.py (which also embeds WB_DATA from data/).
//
// Nakama's JavaScript runtime (goja) needs every registered function to be a
// named top-level function, so the files below only declare functions and
// InitModule (99_init.js) registers them.

var SYSTEM_USER = "00000000-0000-0000-0000-000000000000";
var CODE = { INVALID: 3, NOT_FOUND: 5, EXISTS: 6, DENIED: 7, PRECONDITION: 9, INTERNAL: 13 };

function wbError(message, code) {
  return { message: message, code: code || CODE.INVALID };
}

function nowSec() {
  return Date.now() / 1000.0;
}

function parsePayload(payload) {
  if (!payload || payload === "") return {};
  try {
    var p = JSON.parse(payload);
    if (p === null || typeof p !== "object") throw wbError("Payload must be a JSON object");
    return p;
  } catch (e) {
    if (e && e.code) throw e;
    throw wbError("Payload is not valid JSON");
  }
}

function requireUser(ctx) {
  if (!ctx.userId) throw wbError("Sign in first", CODE.DENIED);
  return ctx.userId;
}

function readOne(nk, collection, key, userId) {
  var res = nk.storageRead([{ collection: collection, key: key, userId: userId }]);
  return res && res.length > 0 ? res[0] : null;
}

function writeOne(nk, collection, key, userId, value, version, permissionRead) {
  var obj = { collection: collection, key: key, userId: userId, value: value,
    permissionRead: permissionRead === undefined ? 1 : permissionRead, permissionWrite: 0 };
  if (version !== undefined && version !== null) obj.version = version;
  return nk.storageWrite([obj])[0];
}

function intOr(v, fallback) {
  var n = parseInt(v, 10);
  return isNaN(n) ? fallback : n;
}

function config(key, fallback) {
  var c = WB_DATA.server;
  var parts = key.split(".");
  for (var i = 0; i < parts.length; i++) {
    if (c === null || typeof c !== "object" || !(parts[i] in c)) return fallback;
    c = c[parts[i]];
  }
  return c;
}

// Pending adjustments the next uploaded save must reflect. Market sales take
// items or gold out ("debit"), purchases and boss rewards put them in
// ("credit"). Each op has a sequence number; the client stores the highest
// sequence it has applied in its save (world.server_ledger_seq) and an
// accepted upload clears only those ops.
function ledgerOp(nk, userId, kind, item, qty) {
  for (var attempt = 0; attempt < 5; attempt++) {
    var obj = readOne(nk, "ledger", "pending", userId);
    var led = obj ? obj.value : { seq: 0, ops: [] };
    led.seq += 1;
    led.ops.push({ seq: led.seq, kind: kind, item: item, qty: qty });
    try {
      writeOne(nk, "ledger", "pending", userId, led, obj ? obj.version : "*", 0);
      return led.seq;
    } catch (e) {
      // Concurrent write: retry with the fresh version.
    }
  }
  throw wbError("Busy, try again", CODE.INTERNAL);
}

function ledgerTotals(led, aboveSeq) {
  var t = { debits: {}, credits: {} };
  var ops = (led && led.ops) || [];
  for (var i = 0; i < ops.length; i++) {
    if (ops[i].seq <= aboveSeq) continue;
    addTo(ops[i].kind === "debit" ? t.debits : t.credits, ops[i].item, ops[i].qty);
  }
  return t;
}

function addTo(map, key, qty) {
  map[key] = (map[key] || 0) + qty;
}

// ---- 10_profile.js ----
// Profile, wallet and cloud saves.
//
// Authority split (see docs/TECHNICAL_ARCHITECTURE.md section 6):
//  * server-authoritative: premium currencies (gems, recruitment and event
//    tokens) in the Nakama wallet, recruitment RNG/pity, market escrow,
//    guilds, the world boss, region presence;
//  * client-simulated, server-validated: the idle simulation itself. Every
//    uploaded save is compared with the last accepted one; gains above the
//    configured rate caps, characters the server never granted, or clocks
//    that run ahead of real time are rejected.

var PREMIUM = ["gems", "recruitment_tokens", "event_tokens"];

function ensureWallet(nk, userId) {
  var flag = readOne(nk, "profile", "init", userId);
  if (flag) return;
  var start = config("starting_wallet", {});
  var change = {};
  for (var i = 0; i < PREMIUM.length; i++) change[PREMIUM[i]] = intOr(start[PREMIUM[i]], 0);
  nk.walletUpdate(userId, change, { reason: "starting_wallet" }, true);
  writeOne(nk, "profile", "init", userId, { at: nowSec() }, "*", 0);
}

function walletOf(nk, userId) {
  var acc = nk.accountGetId(userId);
  var w = acc.wallet || {};
  if (typeof w === "string") w = JSON.parse(w);
  var out = {};
  for (var i = 0; i < PREMIUM.length; i++) out[PREMIUM[i]] = intOr(w[PREMIUM[i]], 0);
  return out;
}

function rpcBootstrap(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  ensureWallet(nk, uid);
  var save = readOne(nk, "saves", "main", uid);
  var granted = readOne(nk, "profile", "granted", uid);
  return JSON.stringify({
    server_time: nowSec(),
    user_id: uid,
    username: ctx.username,
    wallet: walletOf(nk, uid),
    has_save: !!save,
    save_version: save ? save.version : "",
    saved_at: save ? save.value.saved_at : 0,
    granted_characters: granted ? granted.value.ids : [],
    events: activeEvents(),
    boss: bossPublic(nk, ctx),
    pending_deliveries: countDeliveries(nk, uid)
  });
}

// --- Save summaries -----------------------------------------------------------

function itemTotals(world) {
  var t = {};
  var st = (world.storage || {}).items || {};
  for (var k in st) addTo(t, k, intOr(st[k], 0));
  var chars = world.characters || {};
  for (var cid in chars) {
    var inv = (chars[cid].inventory || {}).items || {};
    for (var k2 in inv) addTo(t, k2, intOr(inv[k2], 0));
    var eq = chars[cid].equipment || {};
    for (var slot in eq) if (eq[slot] && eq[slot].item_id) addTo(t, eq[slot].item_id, 1);
  }
  var arm = world.armory || [];
  for (var i = 0; i < arm.length; i++) if (arm[i] && arm[i].item_id) addTo(t, arm[i].item_id, 1);
  var mb = world.mailbox || {};
  for (var k3 in mb) addTo(t, k3, intOr(mb[k3], 0));
  return t;
}

function summarize(world, savedAt) {
  var w = world.wallet || {};
  return {
    saved_at: savedAt,
    sim_time: Number(world.sim_time) || 0,
    gold: intOr((w.balances || {}).gold, 0),
    earned: w.earned || {},
    spent: w.spent || {},
    items: itemTotals(world),
    characters: Object.keys(world.characters || {})
  };
}

// Ops up to the save's sequence are reflected in it: drop them.
function clearAppliedOps(nk, uid, seq) {
  for (var attempt = 0; attempt < 5; attempt++) {
    var obj = readOne(nk, "ledger", "pending", uid);
    if (!obj) return;
    var led = obj.value;
    led.ops = led.ops.filter(function (o) { return o.seq > seq; });
    try {
      writeOne(nk, "ledger", "pending", uid, led, obj.version, 0);
      return;
    } catch (e) {}
  }
}

// a - b per key (entries of a only).
function diffMaps(a, b) {
  var out = {};
  for (var k in a) out[k] = a[k] - (b[k] || 0);
  return out;
}

function sumValues(m) {
  var s = 0;
  for (var k in m) s += m[k];
  return s;
}

// Returns "" when the new save is plausible after the previous one.
function validateSave(prev, next, granted, ledger, elapsed) {
  var hours = Math.max(elapsed, 60) / 3600.0;
  var nChars = Math.max(next.characters.length, 1);
  if (next.sim_time + 1 < prev.sim_time) return "Save is older than the last synced save";
  var maxSim = elapsed + config("validation.clock_slack_seconds", 600);
  if (next.sim_time - prev.sim_time > maxSim) return "Simulation ran ahead of real time";
  var itemCap = config("validation.items_per_character_hour", 2500) * nChars * hours;
  var deb = ledger.debits || {}, cred = ledger.credits || {};
  var gain = 0;
  for (var it in next.items) {
    var d = next.items[it] - (prev.items[it] || 0) - (cred[it] || 0) + (deb[it] || 0);
    if (d > itemCap) return "Too many " + it + " gained since the last sync";
    if (d > 0) gain += d;
  }
  if (gain > itemCap * 1.5) return "Too many items gained since the last sync";
  var goldCap = config("validation.gold_per_character_hour", 40000) * nChars * hours + config("validation.gold_slack", 5000);
  if (next.gold - prev.gold - (cred.gold || 0) + (deb.gold || 0) > goldCap) return "Too much gold gained since the last sync";
  var gachaIds = WB_DATA.gacha_ids;
  var grantedSet = {};
  for (var i = 0; i < granted.length; i++) grantedSet[granted[i]] = true;
  var prevSet = {};
  for (var j = 0; j < prev.characters.length; j++) prevSet[prev.characters[j]] = true;
  var unexplained = 0;
  for (var c = 0; c < next.characters.length; c++) {
    var cid = next.characters[c];
    if (!WB_DATA.character_rarity[cid]) return "Unknown character " + cid;
    if (gachaIds[cid] && !grantedSet[cid] && !prevSet[cid]) unexplained += 1;
  }
  // Wandering-hero encounters can recruit gacha characters without the server.
  if (unexplained > Math.max(1, Math.floor(hours / config("validation.hours_per_encounter_hero", 6)))) return "Characters were added without recruitment";
  return "";
}

// Premium earnings found in the save are credited to the server wallet
// (capped); premium spends made by the simulation are debited.
function premiumDelta(prev, next, hours) {
  var delta = {};
  var cap = config("validation.premium_per_hour", { gems: 200, recruitment_tokens: 6, event_tokens: 6 });
  for (var i = 0; i < PREMIUM.length; i++) {
    var c = PREMIUM[i];
    var earned = Math.max(intOr(next.earned[c], 0) - intOr(prev.earned[c], 0), 0);
    var spent = Math.max(intOr(next.spent[c], 0) - intOr(prev.spent[c], 0), 0);
    earned = Math.min(earned, Math.ceil((cap[c] || 0) * Math.max(hours, 1)));
    if (earned - spent !== 0) delta[c] = earned - spent;
  }
  return delta;
}

function rpcSaveUpload(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  ensureWallet(nk, uid);
  var p = parsePayload(payload);
  var save = p.save;
  if (!save || typeof save !== "object" || !save.world) throw wbError("Missing save.world");
  if (JSON.stringify(save).length > config("validation.max_save_bytes", 4000000)) throw wbError("Save is too large");
  var now = nowSec();
  var next = summarize(save.world, now);
  var prevObj = readOne(nk, "saves", "main", uid);
  if (p.expected_version && prevObj && prevObj.version !== p.expected_version) {
    throw wbError("The cloud save changed on another device", CODE.PRECONDITION);
  }
  var walletChange = {};
  if (prevObj) {
    var prev = prevObj.value.summary;
    var grantedObj = readOne(nk, "profile", "granted", uid);
    var ledObj = readOne(nk, "ledger", "pending", uid);
    // Only ops the save says it applied (seq <= server_ledger_seq) are in it.
    var ledger = ledgerTotals(ledObj ? ledObj.value : null, -1);
    var unapplied = ledgerTotals(ledObj ? ledObj.value : null, intOr(save.world.server_ledger_seq, 0));
    ledger = { debits: diffMaps(ledger.debits, unapplied.debits), credits: diffMaps(ledger.credits, unapplied.credits) };
    var elapsed = now - prev.saved_at;
    var why = validateSave(prev, next, grantedObj ? grantedObj.value.ids : [], ledger, elapsed);
    if (why !== "") {
      logger.warn("save rejected for %s: %s", uid, why);
      return JSON.stringify({ accepted: false, reason: why, wallet: walletOf(nk, uid) });
    }
    walletChange = premiumDelta(prev, next, elapsed / 3600.0);
  }
  var w = walletOf(nk, uid);
  for (var c in walletChange) {
    if (w[c] + walletChange[c] < 0) walletChange[c] = -w[c];
  }
  if (Object.keys(walletChange).length > 0) nk.walletUpdate(uid, walletChange, { reason: "save_sync" }, true);
  var ack = writeOne(nk, "saves", "main", uid, { saved_at: now, summary: next, save: save }, prevObj ? prevObj.version : "*", 1);
  clearAppliedOps(nk, uid, intOr(save.world.server_ledger_seq, 0));
  writePublicTown(nk, uid, ctx.username, save.world);
  return JSON.stringify({ accepted: true, version: ack.version, saved_at: now, wallet: walletOf(nk, uid) });
}

function rpcSaveDownload(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  var obj = readOne(nk, "saves", "main", uid);
  if (!obj) return JSON.stringify({ found: false });
  return JSON.stringify({ found: true, version: obj.version, saved_at: obj.value.saved_at, save: obj.value.save, wallet: walletOf(nk, uid) });
}

// --- Shared towns ---------------------------------------------------------------

function writePublicTown(nk, uid, username, world) {
  var roster = [];
  var chars = world.characters || {};
  for (var cid in chars) {
    roster.push({ id: cid, stars: intOr(chars[cid].stars, 1), xp: Number(chars[cid].character_xp) || 0 });
  }
  writeOne(nk, "town", "public", uid, {
    username: username,
    updated: nowSec(),
    buildings: ((world.town || {}).levels) || {},
    regions: world.unlocked_regions || [],
    roster: roster
  }, undefined, 2);
}

function rpcVisitTown(ctx, logger, nk, payload) {
  requireUser(ctx);
  var p = parsePayload(payload);
  if (!p.user_id) throw wbError("user_id is required");
  var obj = readOne(nk, "town", "public", String(p.user_id));
  if (!obj) throw wbError("That player has not synced a town yet", CODE.NOT_FOUND);
  return JSON.stringify(obj.value);
}

// ---- 20_recruit.js ----
// Server-authoritative recruitment: the same algorithm as
// scripts/recruitment/recruitment_state.gd (the client's offline/dev
// reference), with the RNG, pity counters and history kept on the server.

function rarityRank(r) {
  return WB_DATA.rarity_order.indexOf(r);
}

function findBanner(id) {
  for (var i = 0; i < WB_DATA.banners.length; i++) if (WB_DATA.banners[i].id === id) return WB_DATA.banners[i];
  return null;
}

function rollBase(banner) {
  var r = Math.random();
  var acc = 0, last = "";
  for (var rarity in banner.rates) {
    acc += banner.rates[rarity];
    last = rarity;
    if (r < acc) return rarity;
  }
  return last;
}

function rollRarity(banner, counters) {
  var forced = "";
  var pity = banner.pity || [];
  for (var i = 0; i < pity.length; i++) {
    var tier = pity[i].rarity;
    if ((counters[tier] || 0) + 1 >= pity[i].guaranteed_on_pull) {
      if (forced === "" || rarityRank(tier) > rarityRank(forced)) forced = tier;
    }
  }
  var result = rollBase(banner);
  if (forced !== "" && rarityRank(result) < rarityRank(forced)) result = forced;
  for (var j = 0; j < pity.length; j++) {
    var t = pity[j].rarity;
    counters[t] = rarityRank(result) >= rarityRank(t) ? 0 : (counters[t] || 0) + 1;
  }
  return result;
}

function pickCharacter(banner, rarity) {
  var pool = (WB_DATA.gacha_by_rarity[rarity] || []).slice();
  var f = banner.featured;
  if (f && pool.indexOf(f.character_id) >= 0) {
    if (Math.random() < f.share || pool.length === 1) return f.character_id;
    pool.splice(pool.indexOf(f.character_id), 1);
  }
  if (pool.length === 0) return "";
  return pool[Math.floor(Math.random() * pool.length)];
}

// The cheapest way to pay: a banner token first, otherwise gems (10-pull discount).
function recruitCost(banner, count, wallet) {
  var costs = banner.costs || {};
  for (var cur in costs) {
    if (cur === "gems") continue;
    if ((wallet[cur] || 0) >= costs[cur] * count) {
      var c = {};
      c[cur] = costs[cur] * count;
      return c;
    }
  }
  if (costs.gems !== undefined) {
    var g = costs.gems * count;
    if (count === 10) g = Math.round(g * (banner.ten_pull_discount || 1));
    if ((wallet.gems || 0) >= g) return { gems: g };
  }
  return null;
}

function rpcRecruit(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  ensureWallet(nk, uid);
  var p = parsePayload(payload);
  var banner = findBanner(String(p.banner || ""));
  if (!banner) throw wbError("Unknown banner", CODE.NOT_FOUND);
  var count = intOr(p.count, 1);
  if (count !== 1 && count !== 10) throw wbError("Pull 1 or 10");
  var cost = recruitCost(banner, count, walletOf(nk, uid));
  if (!cost) throw wbError("Not enough tokens or gems", CODE.PRECONDITION);
  var neg = {};
  for (var c in cost) neg[c] = -cost[c];
  // walletUpdate fails (and changes nothing) if a balance would go negative.
  nk.walletUpdate(uid, neg, { reason: "recruit", banner: banner.id, count: count }, true);
  var stateObj = readOne(nk, "recruitment", "state", uid);
  var st = stateObj ? stateObj.value : { pity: {}, total: {}, history: [] };
  var counters = st.pity[banner.id] || {};
  var results = [];
  for (var i = 0; i < count; i++) {
    var rarity = rollRarity(banner, counters);
    results.push({ character_id: pickCharacter(banner, rarity), rarity: rarity, banner: banner.id });
  }
  st.pity[banner.id] = counters;
  st.total[banner.id] = (st.total[banner.id] || 0) + count;
  st.history = results.concat(st.history).slice(0, 100);
  writeOne(nk, "recruitment", "state", uid, st, undefined, 1);
  var gObj = readOne(nk, "profile", "granted", uid);
  var ids = gObj ? gObj.value.ids : [];
  for (var k = 0; k < results.length; k++) if (results[k].character_id && ids.indexOf(results[k].character_id) < 0) ids.push(results[k].character_id);
  writeOne(nk, "profile", "granted", uid, { ids: ids }, undefined, 1);
  return JSON.stringify({ results: results, cost: cost, wallet: walletOf(nk, uid), pity: counters, total: st.total[banner.id] });
}

function rpcRecruitState(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  var stateObj = readOne(nk, "recruitment", "state", uid);
  return JSON.stringify(stateObj ? stateObj.value : { pity: {}, total: {}, history: [] });
}

// ---- 30_market.js ----
// Player marketplace with escrow, plus direct trades between players
// (a listing reserved for one buyer). Gold is the currency; a fee is a gold
// sink. Items leave the seller when listed (ledger debit) and reach the
// buyer as a delivery that the client claims (ledger credit).

var MARKET = "market";

function tradeable(itemId) {
  var it = WB_DATA.items[itemId];
  return !!it && !it.untradeable;
}

function rpcMarketList(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  var p = parsePayload(payload);
  var item = String(p.item || ""), qty = intOr(p.qty, 0), price = intOr(p.price, 0);
  if (!tradeable(item)) throw wbError("This item cannot be traded");
  if (qty <= 0 || qty > 100000) throw wbError("Quantity must be 1 to 100000");
  if (price <= 0 || price > 1000000000) throw wbError("Price must be positive");
  var save = readOne(nk, "saves", "main", uid);
  if (!save) throw wbError("Sync your save before trading", CODE.PRECONDITION);
  // The last synced save plus pending ops must still hold the items.
  var led = readOne(nk, "ledger", "pending", uid);
  var t = ledgerTotals(led ? led.value : null, -1);
  var have = (save.value.summary.items[item] || 0) - (t.debits[item] || 0) + (t.credits[item] || 0);
  if (have < qty) throw wbError("You only have " + have + " " + item + " (as of your last sync)", CODE.PRECONDITION);
  var mine = nk.storageList(uid, MARKET, 100, "");
  if (((mine && mine.objects) || []).length >= config("market.max_listings", 20)) throw wbError("Too many active listings", CODE.PRECONDITION);
  var id = nk.uuidv4();
  var seq = ledgerOp(nk, uid, "debit", item, qty);
  var listing = { id: id, seller: uid, seller_name: ctx.username, item: item, qty: qty, price: price,
    buyer: p.buyer ? String(p.buyer) : "", created: nowSec() };
  // Listings are owned by the seller and publicly readable, so browsing is a
  // plain storage list over the collection.
  writeOne(nk, MARKET, id, uid, listing, "*", 2);
  writeOne(nk, "market_index", id, SYSTEM_USER, { seller: uid, item: item, buyer: listing.buyer }, "*", 2);
  return JSON.stringify({ listing: listing, ledger_seq: seq });
}

function rpcMarketBrowse(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  var p = parsePayload(payload);
  var out = [];
  var cursor = "";
  for (var page = 0; page < 10; page++) {
    var res = nk.storageList(SYSTEM_USER, "market_index", 100, cursor);
    var objs = (res && res.objects) || [];
    for (var i = 0; i < objs.length; i++) {
      var ix = objs[i].value;
      if (p.item && ix.item !== p.item) continue;
      if (ix.buyer && ix.buyer !== uid && ix.seller !== uid) continue;
      var l = readOne(nk, MARKET, objs[i].key, ix.seller);
      if (l) out.push(l.value);
    }
    cursor = res ? res.cursor : "";
    if (!cursor) break;
  }
  out.sort(function (a, b) { return a.price / a.qty - b.price / b.qty; });
  return JSON.stringify({ listings: out.slice(0, 100) });
}

function deliver(nk, userId, items, reason) {
  var id = nk.uuidv4();
  writeOne(nk, "deliveries", id, userId, { id: id, items: items, reason: reason, at: nowSec() }, "*", 1);
}

function rpcMarketBuy(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  var p = parsePayload(payload);
  var ix = readOne(nk, "market_index", String(p.listing_id || ""), SYSTEM_USER);
  if (!ix) throw wbError("That listing is gone", CODE.NOT_FOUND);
  var lObj = readOne(nk, MARKET, ix.key, ix.value.seller);
  if (!lObj) throw wbError("That listing is gone", CODE.NOT_FOUND);
  var l = lObj.value;
  if (l.seller === uid) throw wbError("You cannot buy your own listing");
  if (l.buyer && l.buyer !== uid) throw wbError("This trade is reserved for another player", CODE.DENIED);
  var save = readOne(nk, "saves", "main", uid);
  if (!save) throw wbError("Sync your save before trading", CODE.PRECONDITION);
  var led = readOne(nk, "ledger", "pending", uid);
  var t = ledgerTotals(led ? led.value : null, -1);
  var gold = save.value.summary.gold - (t.debits.gold || 0) + (t.credits.gold || 0);
  if (gold < l.price) throw wbError("Not enough gold (as of your last sync)", CODE.PRECONDITION);
  // Remove the listing first: of two buyers racing, only one delete succeeds.
  try {
    nk.storageDelete([{ collection: "market_index", key: ix.key, userId: SYSTEM_USER, version: ix.version }]);
  } catch (e) {
    throw wbError("That listing was just sold or withdrawn", CODE.NOT_FOUND);
  }
  nk.storageDelete([{ collection: MARKET, key: lObj.key, userId: l.seller }]);
  var seq = ledgerOp(nk, uid, "debit", "gold", l.price);
  var fee = Math.floor(l.price * config("market.fee", 0.05));
  var items = {};
  items[l.item] = l.qty;
  deliver(nk, uid, items, "Bought from " + l.seller_name);
  deliver(nk, l.seller, { gold: l.price - fee }, "Sold " + l.qty + " " + l.item);
  return JSON.stringify({ bought: l, ledger_seq: seq, fee: fee });
}

function rpcMarketCancel(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  var p = parsePayload(payload);
  var lObj = readOne(nk, MARKET, String(p.listing_id || ""), uid);
  if (!lObj) throw wbError("That listing is gone", CODE.NOT_FOUND);
  var ix = readOne(nk, "market_index", lObj.key, SYSTEM_USER);
  if (!ix) throw wbError("That listing is gone", CODE.NOT_FOUND);
  try {
    nk.storageDelete([{ collection: "market_index", key: ix.key, userId: SYSTEM_USER, version: ix.version }]);
  } catch (e) {
    throw wbError("That listing was just sold or withdrawn", CODE.NOT_FOUND);
  }
  nk.storageDelete([{ collection: MARKET, key: lObj.key, userId: uid }]);
  var items = {};
  items[lObj.value.item] = lObj.value.qty;
  deliver(nk, uid, items, "Listing cancelled");
  return JSON.stringify({ cancelled: lObj.value.id });
}

function countDeliveries(nk, uid) {
  var res = nk.storageList(uid, "deliveries", 100, "");
  return ((res && res.objects) || []).length;
}

// Hands every pending delivery to the client and records them as credits.
function rpcClaimDeliveries(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  var res = nk.storageList(uid, "deliveries", 100, "");
  var objs = (res && res.objects) || [];
  var items = {}, notes = [], seq = 0;
  for (var i = 0; i < objs.length; i++) {
    // Deleting with the read version makes a double claim fail.
    try {
      nk.storageDelete([{ collection: "deliveries", key: objs[i].key, userId: uid, version: objs[i].version }]);
    } catch (e) {
      continue;
    }
    for (var it in objs[i].value.items) {
      addTo(items, it, objs[i].value.items[it]);
      seq = ledgerOp(nk, uid, "credit", it, objs[i].value.items[it]);
    }
    notes.push(objs[i].value.reason);
  }
  return JSON.stringify({ items: items, notes: notes, ledger_seq: seq });
}

// ---- 40_guild.js ----
// Guilds are Nakama groups (create, join, members, group chat are built in).
// The module adds guild progression: members donate gold (recorded as a
// ledger debit), the guild levels up, and each level gives every member an
// account-wide bonus the client applies (see WB_DATA.server.guild.perks).

function guildOf(nk, uid) {
  var res = nk.userGroupsList(uid, 10, null, "");
  var gs = (res && res.userGroups) || [];
  for (var i = 0; i < gs.length; i++) {
    // state: 0 superadmin, 1 admin, 2 member, 3 join request
    if (gs[i].state <= 2) return gs[i].group;
  }
  return null;
}

function guildLevel(xp) {
  var levels = config("guild.level_xp", [0, 5000, 20000, 60000, 150000]);
  var lv = 1;
  for (var i = 0; i < levels.length; i++) if (xp >= levels[i]) lv = i + 1;
  return lv;
}

function guildState(nk, groupId) {
  var obj = readOne(nk, "guild", groupId, SYSTEM_USER);
  var v = obj ? obj.value : { xp: 0, donations: {} };
  var lv = guildLevel(v.xp);
  var perks = config("guild.perks", {});
  return { group_id: groupId, xp: v.xp, level: lv, donations: v.donations, perks: perks[String(lv)] || {}, version: obj ? obj.version : "*" };
}

function rpcGuildInfo(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  var g = guildOf(nk, uid);
  if (!g) return JSON.stringify({ in_guild: false });
  var st = guildState(nk, g.id);
  delete st.version;
  st.in_guild = true;
  st.name = g.name;
  return JSON.stringify(st);
}

function rpcGuildDonate(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  var p = parsePayload(payload);
  var gold = intOr(p.gold, 0);
  if (gold <= 0) throw wbError("Donate a positive amount of gold");
  var g = guildOf(nk, uid);
  if (!g) throw wbError("Join a guild first", CODE.PRECONDITION);
  var save = readOne(nk, "saves", "main", uid);
  if (!save) throw wbError("Sync your save first", CODE.PRECONDITION);
  var led = readOne(nk, "ledger", "pending", uid);
  var t = ledgerTotals(led ? led.value : null, -1);
  if (save.value.summary.gold - (t.debits.gold || 0) + (t.credits.gold || 0) < gold) throw wbError("Not enough gold (as of your last sync)", CODE.PRECONDITION);
  var seq = ledgerOp(nk, uid, "debit", "gold", gold);
  for (var attempt = 0; attempt < 5; attempt++) {
    var st = guildState(nk, g.id);
    st.donations[uid] = (st.donations[uid] || 0) + gold;
    try {
      writeOne(nk, "guild", g.id, SYSTEM_USER, { xp: st.xp + gold, donations: st.donations }, st.version, 2);
      var after = guildState(nk, g.id);
      delete after.version;
      after.ledger_seq = seq;
      return JSON.stringify(after);
    } catch (e) {}
  }
  throw wbError("Busy, try again", CODE.INTERNAL);
}

// ---- 50_boss.js ----
// Co-op world boss shared by every player. A player can strike once per
// cooldown; damage comes from the power of their best characters in their
// last synced save (computed here, never sent by the client). When the boss
// falls, everyone who hit it gets rewards by delivery and a new boss spawns.

function bossDefs() {
  return config("world_boss.bosses", []);
}

// Tests start the server with --runtime.env WB_BOSS_HP=<n> to get a boss
// they can defeat quickly. Never set in production. (Read from ctx.env each
// time: Nakama runs RPCs in a pool of JS VMs that do not share globals.)
function newBoss(index, ctx) {
  var defs = bossDefs();
  var d = defs[index % defs.length];
  var override = ctx && ctx.env ? intOr(ctx.env.WB_BOSS_HP, 0) : 0;
  var hp = override > 0 ? override : d.hp;
  return { index: index, id: d.id, name: d.name, max_hp: hp, hp: hp, spawned: nowSec(), hits: {}, rewards: d.rewards };
}

function bossObj(nk, ctx) {
  var obj = readOne(nk, "world_boss", "current", SYSTEM_USER);
  var override = ctx && ctx.env ? intOr(ctx.env.WB_BOSS_HP, 0) : 0;
  if (obj && override > 0 && obj.value.max_hp > override) {
    // Test server started on a database that already has a full-size boss.
    obj.value.max_hp = override;
    obj.value.hp = Math.min(obj.value.hp, override);
    try { writeOne(nk, "world_boss", "current", SYSTEM_USER, obj.value, obj.version, 2); } catch (e) {}
    obj = readOne(nk, "world_boss", "current", SYSTEM_USER);
  }
  if (obj) return obj;
  try {
    writeOne(nk, "world_boss", "current", SYSTEM_USER, newBoss(0, ctx), "*", 2);
  } catch (e) {}
  return readOne(nk, "world_boss", "current", SYSTEM_USER);
}

function bossPublic(nk, ctx) {
  var b = bossObj(nk, ctx).value;
  var top = [];
  for (var u in b.hits) top.push({ user_id: u, name: b.hits[u].name, damage: b.hits[u].damage });
  top.sort(function (a, c) { return c.damage - a.damage; });
  return { id: b.id, name: b.name, hp: b.hp, max_hp: b.max_hp, index: b.index, top: top.slice(0, 10), fighters: top.length };
}

// Damage per strike: sum of the best three characters' character levels and
// stars, scaled, with +-20% variance.
function strikePower(summarySave) {
  var chars = (summarySave.world && summarySave.world.characters) || {};
  var powers = [];
  for (var cid in chars) {
    var xp = Number(chars[cid].character_xp) || 0;
    var lv = 1;
    var table = WB_DATA.character_xp_table;
    for (var i = 0; i < table.length; i++) if (xp >= table[i]) lv = i + 1;
    powers.push(lv * 10 + intOr(chars[cid].stars, 1) * 25);
  }
  powers.sort(function (a, c) { return c - a; });
  var sum = 0;
  for (var j = 0; j < Math.min(3, powers.length); j++) sum += powers[j];
  return Math.max(1, Math.round(sum * (0.8 + Math.random() * 0.4)));
}

function rpcBossStatus(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  var pub = bossPublic(nk, ctx);
  var cd = readOne(nk, "world_boss_cd", "last", uid);
  var wait = cd ? Math.max(0, cd.value.at + config("world_boss.cooldown_seconds", 600) - nowSec()) : 0;
  pub.cooldown_remaining = wait;
  return JSON.stringify(pub);
}

function rpcBossAttack(ctx, logger, nk, payload) {
  var uid = requireUser(ctx);
  var cooldown = config("world_boss.cooldown_seconds", 600);
  var cd = readOne(nk, "world_boss_cd", "last", uid);
  if (cd && nowSec() - cd.value.at < cooldown) throw wbError("Your heroes are still recovering", CODE.PRECONDITION);
  var save = readOne(nk, "saves", "main", uid);
  if (!save) throw wbError("Sync your save first", CODE.PRECONDITION);
  var dmg = strikePower(save.value.save);
  for (var attempt = 0; attempt < 8; attempt++) {
    var obj = bossObj(nk, ctx);
    var b = obj.value;
    var dealt = Math.min(dmg, b.hp);
    b.hp -= dealt;
    var h = b.hits[uid] || { name: ctx.username, damage: 0 };
    h.damage += dealt;
    b.hits[uid] = h;
    var defeated = b.hp <= 0;
    var next = defeated ? newBoss(b.index + 1, ctx) : b;
    try {
      writeOne(nk, "world_boss", "current", SYSTEM_USER, next, obj.version, 2);
    } catch (e) {
      continue; // someone else hit it at the same time; retry on fresh state
    }
    writeOne(nk, "world_boss_cd", "last", uid, { at: nowSec() }, undefined, 0);
    if (defeated) {
      for (var u in b.hits) deliver(nk, u, b.rewards, "Defeated " + b.name);
      var gemsEach = config("world_boss.gems_reward", 50);
      for (var u2 in b.hits) nk.walletUpdate(u2, { gems: gemsEach }, { reason: "world_boss", boss: b.id }, true);
    }
    return JSON.stringify({ damage: dealt, defeated: defeated, boss: bossPublic(nk, ctx), cooldown_seconds: cooldown });
  }
  throw wbError("Busy, try again", CODE.INTERNAL);
}

// ---- 60_world.js ----
// Global world events (server clock, data-driven) and region presence.

function activeEvents() {
  var out = [];
  var now = nowSec();
  var evs = config("world_events", []);
  for (var i = 0; i < evs.length; i++) {
    var e = evs[i];
    // Repeating events: active for `duration` seconds out of every `period`.
    var phase = ((now - e.epoch) % e.period + e.period) % e.period;
    if (phase < e.duration) out.push({ id: e.id, name: e.name, description: e.description, effects: e.effects, ends_at: now - phase + e.duration });
  }
  return out;
}

function rpcWorldEvents(ctx, logger, nk, payload) {
  return JSON.stringify({ server_time: nowSec(), events: activeEvents() });
}

// One authoritative match per region relays where other players' heroes are.
// Clients send OP_POS {x, y, sprite, name} about once a second; the match
// broadcasts OP_STATE with every presence's last position once a second.
var OP_POS = 1, OP_STATE = 2;

function rpcRegionMatch(ctx, logger, nk, payload) {
  requireUser(ctx);
  var p = parsePayload(payload);
  var region = String(p.region || "");
  if (WB_DATA.regions.indexOf(region) < 0) throw wbError("Unknown region");
  // One live match per region. The match id is kept in system storage
  // because matchList's label index updates asynchronously, so two players
  // arriving together would otherwise each create their own match.
  var max = config("presence.max_per_match", 100);
  for (var attempt = 0; attempt < 4; attempt++) {
    var rec = readOne(nk, "presence", region, SYSTEM_USER);
    if (rec && rec.value.match_id) {
      var m = null;
      try { m = nk.matchGet(rec.value.match_id); } catch (e) { m = null; }
      if (m && m.size < max) return JSON.stringify({ match_id: rec.value.match_id });
    }
    var id = nk.matchCreate("region_presence", { region: region });
    try {
      writeOne(nk, "presence", region, SYSTEM_USER, { match_id: id }, rec ? rec.version : "*", 0);
      return JSON.stringify({ match_id: id });
    } catch (e) {
      // Another player registered a match first; the unused one closes
      // itself after its empty timeout. Read again and join theirs.
    }
  }
  throw wbError("Region is busy, try again");
}

function regionMatchInit(ctx, logger, nk, params) {
  return { state: { region: params.region, players: {}, empty_ticks: 0 }, tickRate: 1, label: "region:" + params.region };
}

function regionMatchJoinAttempt(ctx, logger, nk, dispatcher, tick, state, presence, metadata) {
  return { state: state, accept: Object.keys(state.players).length < config("presence.max_per_match", 100) };
}

function regionMatchJoin(ctx, logger, nk, dispatcher, tick, state, presences) {
  for (var i = 0; i < presences.length; i++) {
    state.players[presences[i].userId] = { name: presences[i].username, x: -1, y: -1, sprite: "", heroes: [] };
  }
  return { state: state };
}

function regionMatchLeave(ctx, logger, nk, dispatcher, tick, state, presences) {
  for (var i = 0; i < presences.length; i++) delete state.players[presences[i].userId];
  return { state: state };
}

function regionMatchLoop(ctx, logger, nk, dispatcher, tick, state, messages) {
  for (var i = 0; i < messages.length; i++) {
    var m = messages[i];
    if (m.opCode !== OP_POS || !state.players[m.sender.userId]) continue;
    try {
      var d = JSON.parse(nk.binaryToString(m.data));
      var heroes = [];
      var src = d.heroes || [];
      for (var j = 0; j < Math.min(src.length, 12); j++) {
        heroes.push({ id: String(src[j].id).slice(0, 40), x: intOr(src[j].x, -1), y: intOr(src[j].y, -1) });
      }
      state.players[m.sender.userId].heroes = heroes;
    } catch (e) {}
  }
  if (Object.keys(state.players).length === 0) {
    state.empty_ticks += 1;
    if (state.empty_ticks > config("presence.empty_seconds_before_close", 60)) return null;
  } else {
    state.empty_ticks = 0;
    dispatcher.broadcastMessage(OP_STATE, JSON.stringify({ region: state.region, players: state.players }), null, null, true);
  }
  return { state: state };
}

function regionMatchTerminate(ctx, logger, nk, dispatcher, tick, state, graceSeconds) {
  return { state: state };
}

function regionMatchSignal(ctx, logger, nk, dispatcher, tick, state, data) {
  return { state: state, data: data };
}

// ---- 99_init.js ----
function InitModule(ctx, logger, nk, initializer) {
  if (ctx.env && ctx.env.WB_BOSS_HP) logger.warn("World boss HP override active: %s (test setting)", ctx.env.WB_BOSS_HP);
  initializer.registerRpc("wb_bootstrap", rpcBootstrap);
  initializer.registerRpc("wb_save_upload", rpcSaveUpload);
  initializer.registerRpc("wb_save_download", rpcSaveDownload);
  initializer.registerRpc("wb_visit_town", rpcVisitTown);
  initializer.registerRpc("wb_recruit", rpcRecruit);
  initializer.registerRpc("wb_recruit_state", rpcRecruitState);
  initializer.registerRpc("wb_market_list", rpcMarketList);
  initializer.registerRpc("wb_market_browse", rpcMarketBrowse);
  initializer.registerRpc("wb_market_buy", rpcMarketBuy);
  initializer.registerRpc("wb_market_cancel", rpcMarketCancel);
  initializer.registerRpc("wb_claim_deliveries", rpcClaimDeliveries);
  initializer.registerRpc("wb_guild_info", rpcGuildInfo);
  initializer.registerRpc("wb_guild_donate", rpcGuildDonate);
  initializer.registerRpc("wb_boss_status", rpcBossStatus);
  initializer.registerRpc("wb_boss_attack", rpcBossAttack);
  initializer.registerRpc("wb_world_events", rpcWorldEvents);
  initializer.registerRpc("wb_region_match", rpcRegionMatch);
  initializer.registerMatch("region_presence", {
    matchInit: regionMatchInit,
    matchJoinAttempt: regionMatchJoinAttempt,
    matchJoin: regionMatchJoin,
    matchLeave: regionMatchLeave,
    matchLoop: regionMatchLoop,
    matchTerminate: regionMatchTerminate,
    matchSignal: regionMatchSignal
  });
  logger.info("Worldbound server module %s loaded (%d banners, %d items)", WB_DATA.version, WB_DATA.banners.length, Object.keys(WB_DATA.items).length);
}
